-- ============================================================================
-- HACKATHON ONLY (iterahq/hackathon-colosseum, Supabase nyzcbnnbffsizshiolbh).
-- Shop v3, step 3: profile borders, a new item kind `border`.
--
-- * The avatar art already carries a ring. A border is drawn BY THE FRONT END on
--   top of it, from `effect.border = { style, colors, glow, animated }`, so no
--   art is needed. `style` is solid | gradient | conic | dashed | double.
-- * For sale on their own: bronze, emerald, pixel, circuit, crystal, laurel
--   (crystals; SOL list price = crystals / 500 in US$, at least US$ 0.20).
-- * Signature borders (one per epic-or-higher avatar) have no price: they only
--   come with their avatar (`effect.includes`, step 4). `border_none` is the
--   default everybody wears (the art's own ring).
-- * Owned through `itera.user_inventory` (global ref). The one worn is
--   `itera.learner_themes.border_key` (no row, or not owned any more = none).
--
-- Colours were picked from the published chips (tera-avatars/<key>_chip.webp).
-- Additive and idempotent.
-- ============================================================================

on conflict (key) do nothing;

alter table itera.learner_themes add column if not exists border_key text references itera.shop_items(key);
